"""Route-conditioned ego progress for the T4 PDM oracle.

The scorer does not train a trajectory-closeness head. Its ``EP`` target is the
NAVSIM/PDM progress sub-score: project the proposal's current and final ego
positions onto the reference driving centerline, keep only forward progress,
apply the multiplicative safety/map gates, and normalize by the reference
planner's progress (with NAVSIM's 5 m threshold rule).

The PDM-Closed training cache supplies that reference progress from the
PDM-Closed planner.  T4 does not provide a NAVSIM ``PDMPath`` or metric cache,
so the adapter accepts an explicit ``pdm_progress`` scalar when a T4 oracle
precomputation provides one.  If it is absent, it uses the demonstrated future
endpoint only as a clearly marked route-progress fallback.  That fallback is
not a demonstrated-trajectory closeness proxy, and it is not claimed to be
bit-identical to PDM-Closed.
"""

from __future__ import annotations

from typing import Any, Sequence

import numpy as np


PROGRESS_DISTANCE_THRESHOLD = 5.0


def _to_numpy(value: Any) -> np.ndarray:
    if hasattr(value, "detach"):
        value = value.detach().cpu().numpy()
    return np.asarray(value)


def merge_route_centerlines(route_centerlines: Sequence[Any]) -> np.ndarray:
    """Concatenate ordered, zero-padding-free T4 route lane polylines.

    T4 stores the route as up to 25 ordered lane segments, each in a fixed
    20-point slot.  The segment order is part of the dataset contract.  Empty
    rows have already been removed by the map extractor, but this function
    also filters malformed/short rows and removes a repeated join vertex.
    """

    chunks: list[np.ndarray] = []
    for raw in route_centerlines:
        values = np.asarray(raw, dtype=np.float64)
        if values.ndim != 2 or values.shape[-1] < 2:
            continue
        values = values[:, :2]
        finite = np.isfinite(values).all(axis=-1)
        values = values[finite]
        if values.shape[0] < 2:
            continue
        if chunks and np.allclose(chunks[-1][-1], values[0], rtol=0.0, atol=1.0e-8):
            values = values[1:]
        if values.shape[0]:
            chunks.append(values)
    if not chunks:
        return np.zeros((0, 2), dtype=np.float64)
    return np.concatenate(chunks, axis=0)


def route_conditioned_ep_numpy(
    proposals: Any,
    reference: Any,
    route_centerlines: Sequence[Sequence[Any]],
    multiplicative: Any,
    pdm_progress: Any | None = None,
) -> np.ndarray:
    """Compute the original PDM EP formula for a T4 batch on the CPU.

    ``proposals`` is ``[B,N,T,4]`` and ``reference`` is ``[B,T,4]``; both use
    ``(x,y,cos_yaw,sin_yaw)`` and contain *future* samples only.  The current
    ego origin is inserted implicitly, matching ``PDMScorer``'s
    initial-state-inclusive simulation.

    ``multiplicative`` is the original PDM multiplicative gate, i.e. ``NC×DAC``
    for the PDM contract. DDC is a separately predicted weighted head and has
    zero default weight in the default metric profile; callers
    must not silently fold it into this gate.

    ``pdm_progress`` is the per-scene raw progress of the PDM-Closed reference
    (already carrying the reference multiplicative gate), matching the
    ``pdm_progress`` field consumed by the PDM scorer. When it
    is omitted, the T4 route-projected demonstrated endpoint is used as an
    explicit data-adaptation fallback.
    """

    pred = _to_numpy(proposals).astype(np.float64, copy=False)
    ref = _to_numpy(reference).astype(np.float64, copy=False)
    gate = _to_numpy(multiplicative).astype(np.float64, copy=False)
    if pred.ndim != 4 or pred.shape[-1] < 2:
        raise ValueError(f"proposals must be [B,N,T,>=2], got {pred.shape}")
    if ref.ndim != 3 or ref.shape[0] != pred.shape[0] or ref.shape[-1] < 2:
        raise ValueError(f"reference must be [B,T,>=2], got {ref.shape}")
    if gate.shape != pred.shape[:2]:
        raise ValueError(
            f"multiplicative gates must have shape {pred.shape[:2]}, got {gate.shape}"
        )
    if len(route_centerlines) != pred.shape[0]:
        raise ValueError("route centerline batch does not match proposals")

    baseline_progress: np.ndarray | None = None
    if pdm_progress is not None:
        baseline_progress = _to_numpy(pdm_progress).astype(np.float64, copy=False)
        if baseline_progress.shape == (pred.shape[0], 1):
            baseline_progress = baseline_progress[:, 0]
        if baseline_progress.shape != (pred.shape[0],):
            raise ValueError(
                "pdm_progress must have shape [B] (or [B,1]), got "
                f"{baseline_progress.shape}"
            )
        if not np.isfinite(baseline_progress).all() or (baseline_progress < 0.0).any():
            raise ValueError("pdm_progress must contain finite non-negative values")

    # Import lazily so the data/model modules remain importable in a minimal
    # environment; the T4 oracle already requires Shapely for its CPU metric
    # backend when this function is used.
    from shapely.geometry import LineString, Point

    result = np.ones(pred.shape[:2], dtype=np.float64)
    origin = Point(0.0, 0.0)
    for batch_index, rows in enumerate(route_centerlines):
        line_xy = merge_route_centerlines(rows)
        if line_xy.shape[0] < 2:
            raise ValueError(
                f"T4 route centerline is empty/degenerate for batch index {batch_index}"
            )
        line = LineString(line_xy)
        start_s = float(line.project(origin))
        if baseline_progress is None:
            reference_end_s = float(
                line.project(
                    Point(
                        float(ref[batch_index, -1, 0]),
                        float(ref[batch_index, -1, 1]),
                    )
                )
            )
            reference_progress = max(reference_end_s - start_s, 0.0)
        else:
            reference_progress = float(baseline_progress[batch_index])
        for proposal_index in range(pred.shape[1]):
            proposal_end_s = float(
                line.project(
                    Point(
                        float(pred[batch_index, proposal_index, -1, 0]),
                        float(pred[batch_index, proposal_index, -1, 1]),
                    )
                )
            )
            raw_progress = max(proposal_end_s - start_s, 0.0)
            gated_progress = raw_progress * gate[batch_index, proposal_index]
            maximum = max(reference_progress, gated_progress)
            if maximum > PROGRESS_DISTANCE_THRESHOLD:
                result[batch_index, proposal_index] = np.clip(
                    gated_progress / maximum, 0.0, 1.0
                )
            else:
                # Exact PDMScorer behavior: a short/slow reference is gated to
                # EP=1 unless a multiplicative metric already zeroed the plan.
                result[batch_index, proposal_index] = (
                    0.0 if gate[batch_index, proposal_index] == 0.0 else 1.0
                )
    return result.astype(np.float32)
